begin;
create or replace function public.swift_district_map(p_zone text) returns jsonb language sql stable security definer set search_path='' as $$select jsonb_build_object('zone_id',z.id,'name',z.name,'district_id',d.id,'boundary',d.boundary,'coverage',z.coverage) from public.swift_service_zones z join public.swift_districts d on d.id=z.district_id where z.id=p_zone$$;
revoke all on function public.swift_district_map(text) from public;grant execute on function public.swift_district_map(text) to anon,authenticated;
CREATE OR REPLACE FUNCTION public.swift_region_quote(p_items jsonb, p_coordinates text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO '' AS $function$ declare item jsonb;zid text;current_zone text;z public.swift_service_zones;reg public.swift_store_registry;m public.merchant_storefronts;p text[];lat float8;lng float8;km numeric:=0;d numeric;r jsonb;fee integer;offers public.swift_store_offers; begin if jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items) not between 1 and 100 then raise exception 'Choose items first';end if; if coalesce(p_coordinates,'') ~ '^\s*-?[0-9]+(\.[0-9]+)?\s*,\s*-?[0-9]+(\.[0-9]+)?\s*$' then p:=string_to_array(replace(p_coordinates,' ',''),',');lat:=p[1]::float8;lng:=p[2]::float8;end if; for item in select value from jsonb_array_elements(p_items) loop if nullif(item->>'offer_id','') is not null then
 select * into offers from public.swift_store_offers where id=(item->>'offer_id')::uuid and category=item->>'category' and published;
 if not found or offers.pickup_lat is null or offers.pickup_lng is null then raise exception 'This offer needs a confirmed local pickup';end if;
 current_zone:=public.swift_zone_at(offers.pickup_lat,offers.pickup_lng);
 if current_zone is null then raise exception 'This offer is outside active coverage';end if;
 elsif item->>'category'=any(array['Snack','Drink','Household','Hygiene','Vegetables','Treats']) then
 current_zone:=case when lat is null then 'orange-walk' else public.swift_zone_at(lat,lng) end;if current_zone is null then raise exception 'Pin your delivery location inside an active service area';end if;
 else
 select * into reg from public.swift_store_registry where category=item->>'category';current_zone:=coalesce(reg.zone_id,'orange-walk');if reg.category is not null and reg.status<>'live' then raise exception 'A store is not available for ordering';end if;
 end if; if zid is not null and zid<>current_zone then raise exception 'Choose stores from the same service zone';end if;zid:=current_zone; if nullif(item->>'offer_id','') is not null then
 d:=6371*2*asin(least(1,sqrt(power(sin(radians(offers.pickup_lat-lat)/2),2)+cos(radians(lat))*cos(radians(offers.pickup_lat))*power(sin(radians(offers.pickup_lng-lng)/2),2))));km:=greatest(km,d);
 elsif not(item->>'category'=any(array['Snack','Drink','Household','Hygiene','Vegetables','Treats'])) then
 select * into m from public.merchant_storefronts where category=item->>'category';if m.latitude is not null and lat is not null then d:=6371*2*asin(least(1,sqrt(power(sin(radians(m.latitude-lat)/2),2)+cos(radians(lat))*cos(radians(m.latitude))*power(sin(radians(m.longitude-lng)/2),2))));km:=greatest(km,d);elsif current_zone<>'orange-walk' then raise exception 'A confirmed store and delivery pin are required';end if;
 end if; end loop; select * into z from public.swift_service_zones where id=zid; if not found or not z.active or not z.rates_approved then raise exception 'SwiftShop is not taking orders in this zone yet';end if; if zid='orange-walk' then if lat is not null and public.swift_district_at(lat,lng) is distinct from z.district_id then raise exception 'Your delivery pin is outside this store district';end if;fee:=350; else if public.swift_zone_at(lat,lng) is distinct from zid then raise exception 'Your delivery pin is outside this service zone';end if; select (value->>'fee_cents')::integer into fee from jsonb_array_elements(z.rate_brackets) where (value->>'max_km')::numeric>=km order by (value->>'max_km')::numeric limit 1; if fee is null then raise exception 'This delivery is outside the approved distance range';end if; end if; return jsonb_build_object('zone_id',zid,'district_id',z.district_id,'fee_cents',fee,'distance_km',round(km,2),'rates_updated_at',z.updated_at); end$function$;
CREATE OR REPLACE FUNCTION public.swift_merchant_validate_delivery() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $function$declare q jsonb;begin if tg_op<>'INSERT' then return new;end if; if exists(select 1 from public.customer_order_tracking where id=new.id) then return new;end if; if coalesce(new.snapshot->>'pickup_service','false')='true' then new.zone_id:=public.swift_zone_at(split_part(new.snapshot->>'pickup_location',',',1)::float8,split_part(new.snapshot->>'pickup_location',',',2)::float8);if new.zone_id is null then raise exception 'Pickup service is not active in this area';end if;return new;end if; if jsonb_array_length(coalesce(new.snapshot->'items','[]'::jsonb))=0 and nullif(new.snapshot->>'taco_note','') is not null then new.zone_id:='orange-walk';if (new.snapshot->>'delivery_fee')::numeric is distinct from 3.50 then raise exception 'Delivery fee changed';end if;return new;end if; q:=public.swift_region_quote(new.snapshot->'items',new.snapshot->>'customer_location');new.zone_id:=q->>'zone_id'; if (new.snapshot->>'delivery_fee')::numeric is distinct from (q->>'fee_cents')::numeric/100 or coalesce((new.snapshot->>'platform_fee')::numeric,0)<>0 then raise exception 'Delivery fee changed. Refresh checkout before sending the order';end if; new.snapshot:=new.snapshot||jsonb_build_object('service_zone',new.zone_id,'district_id',q->>'district_id'); new.snapshot:=new.snapshot||jsonb_build_object('local_shopping',coalesce(new.snapshot->'gift','null'::jsonb)='null'::jsonb and jsonb_array_length(new.snapshot->'items')>0 and not exists(select 1 from jsonb_array_elements(new.snapshot->'items') i where not(i->>'category'=any(array['Snack','Drink','Household','Hygiene','Vegetables','Treats'])) or nullif(i->>'offer_id','') is not null)); if (new.snapshot->>'local_shopping')::boolean then new.snapshot:=new.snapshot||jsonb_build_object('routes',jsonb_build_array('https://www.google.com/maps/dir/?api=1&destination='||(new.snapshot->>'customer_location')),'shopping_instructions','Buy these items from a nearby store. After buying everything, start delivery from your current GPS location to the customer.');end if;return new; end$function$;
alter table public.orders add column if not exists local_shopping boolean not null default false;
alter table public.orders add column if not exists shopping_started_at timestamptz;
create or replace function public.swift_local_shopping_guard() returns trigger language plpgsql security definer set search_path='' as $$declare snap jsonb;begin
 if tg_op='INSERT' then
 select snapshot into snap from public.customer_order_tracking where id=new.customer_tracking_id;
 new.local_shopping:=coalesce((snap->>'local_shopping')::boolean,false);
 new.shopping_started_at:=null;
 if new.local_shopping then new.run_kind:='shopping_list';new.run_stops:='[]'::jsonb;new.next_stop:=0;new.pickup_location:=null;new.dropoff_location:=snap->>'customer_location';new.gps_link:='https://www.google.com/maps/dir/?api=1&destination='||(snap->>'customer_location');new.route_notes:=coalesce(new.route_notes,'')||E'\nShop at a nearby store. After buying everything, start delivery using current GPS.';end if;
 else
 if new.local_shopping is distinct from old.local_shopping then raise exception 'Shopping mode cannot change';end if;
 if new.shopping_started_at is distinct from old.shopping_started_at and current_setting('swiftshop.shopping_start',true) is distinct from old.order_id then raise exception 'Use the verified shopping start action';end if;
 if old.local_shopping and new.status='On the Way' and old.status is distinct from new.status and current_setting('swiftshop.shopping_start',true) is distinct from old.order_id then raise exception 'Start local shopping delivery with a fresh GPS position';end if;
 end if;return new;end$$;
drop trigger if exists zzzzz_local_shopping_guard on public.orders;
create trigger zzzzz_local_shopping_guard before insert or update on public.orders for each row execute function public.swift_local_shopping_guard();
create or replace function public.swift_start_local_shopping(p_order_id text,p_lat double precision,p_lng double precision,p_accuracy double precision,p_recorded_at timestamptz) returns public.orders language plpgsql security definer set search_path='' as $$declare r public.orders;begin
 if public.swift_worker_kind() is distinct from 'runner' then raise exception 'Approved runner required';end if;
 select * into r from public.orders where order_id=p_order_id for update;
 if not found or r.assigned_runner_id is distinct from auth.uid() or not r.local_shopping then raise exception 'This is not your local shopping run';end if;
 if r.status='On the Way' and r.shopping_started_at is not null then return r;end if;
 if r.status<>'Claimed' then raise exception 'Claim the run before starting delivery';end if;
 if p_lat is null or p_lng is null or p_lat not between -90 and 90 or p_lng not between -180 and 180 or p_accuracy is null or p_accuracy not between 0 and 50 or p_recorded_at is null or p_recorded_at<now()-interval '30 seconds' or p_recorded_at>now()+interval '5 seconds' then raise exception 'A fresh GPS position within 50 metres is required';end if;
 if public.swift_zone_at(p_lat,p_lng) is distinct from r.zone_id then raise exception 'Your shopping location is outside this run service area';end if;
 perform set_config('swiftshop.shopping_start',r.order_id,true);
 update public.orders set shopping_started_at=now() where order_id=r.order_id;
 r:=public.set_run_status(p_order_id,'On the Way');perform set_config('swiftshop.shopping_start','',true);return r;end$$;
revoke all on function public.swift_start_local_shopping(text,double precision,double precision,double precision,timestamptz) from public;grant execute on function public.swift_start_local_shopping(text,double precision,double precision,double precision,timestamptz) to authenticated;
revoke all on function public.swift_local_shopping_guard() from public;
notify pgrst,'reload schema';
commit;
